// Backend & APIs (category 'backend') — 105 linkless Question Bank rows for
// full-stack "product engineer" loops. answer_hints = the 4–6 key points the
// scorecard grades against ("·" separates them). sort_order puts the
// must-haves first.

const q = (title, difficulty, topics, answer_hints) => ({ title, difficulty, topics, answer_hints })

const ROWS = [
  // ---- API design (8)
  q('Cursor vs offset pagination — when do you use which, and how do you implement a cursor?', 'medium', ['API design', 'Must-have'],
    'offset/limit is simple and allows page jumps but skips or duplicates rows when data changes and gets slow at deep offsets (the DB still scans skipped rows) · cursor = an opaque token encoding the last row\'s sort key plus a unique tiebreaker (created_at, id) · query WHERE (created_at, id) < (cursor) ORDER BY created_at DESC, id DESC LIMIT n+1 to know hasNext · needs a stable sort and a matching composite index · cursor fits infinite scroll and feeds, offset fits admin tables with page numbers'),
  q('REST vs GraphQL vs tRPC — how do you choose for a new product?', 'hard', ['API design', 'Must-have'],
    'REST: resource URLs, HTTP caching and CDNs work out of the box, simple for public APIs · GraphQL: client picks fields, one round trip for nested data, schema as contract, but caching, N+1 (needs DataLoader) and query-cost limits are on you · tRPC: end-to-end TypeScript types with no codegen, best when one team owns a TS client and server (monorepo), not for public or polyglot clients · decide by consumers (public, mobile, internal), team and caching needs'),
  q('What is an idempotency key and how would you implement one for a payment or order API?', 'hard', ['API design', 'Must-have'],
    'client sends a unique Idempotency-Key header per logical operation and reuses it on retries · server stores key + request hash + response (unique constraint) and returns the stored response on a repeat · a different body with the same key is rejected (409/422) · handle concurrent duplicates with a lock or insert-first, in-progress state · keys expire after a TTL (e.g. 24h) · makes retries after timeouts safe for POST'),
  q('How do you version a public API without breaking clients?', 'medium', ['API design'],
    'prefer additive, backward-compatible changes (new optional fields, never repurpose a field) · URL versioning (/v2) is explicit, header or date-based versioning (Stripe-style) keeps URLs stable · deprecation policy: announce, Deprecation/Sunset headers, usage metrics per version · contract tests and a changelog · only bump the major version for breaking changes'),
  q('Design an error contract for an API that a frontend consumes.', 'medium', ['API design', 'Must-have'],
    'correct HTTP status classes (400 validation, 401 unauthenticated, 403 forbidden, 404, 409 conflict, 422, 429 with Retry-After, 5xx) · a consistent JSON body (code, message, details, requestId), e.g. RFC 9457 problem+json · field-level validation errors the form can map to inputs · stable machine-readable codes the UI switches on, never parse messages · no stack traces or internals leaked · the requestId links the UI error to server logs'),
  q('Webhooks vs polling vs SSE — how do you get updates from another system?', 'medium', ['API design'],
    'polling is simple but wasteful and laggy, use backoff and ETags · webhooks push events to your endpoint: verify the HMAC signature, respond 2xx fast and process async, expect retries and duplicates (idempotent handlers, event ids), events can arrive out of order · SSE/WebSocket for pushing to browsers · usually a webhook into the backend, then SSE to the UI'),
  q('How do you design APIs that support optimistic UI?', 'hard', ['API design'],
    'client-generated ids (UUIDs) so the UI can create a row before the server answers · mutations return the full updated resource so the cache reconciles · version or updated_at for conflict detection (409 or If-Match/ETag) · idempotent retries · clear error codes so the UI can roll back with a precise message · batch or ordering semantics for rapid edits'),
  q('How do you let clients request only the fields they need from a REST API?', 'easy', ['API design'],
    'sparse fieldsets (?fields=id,name) or JSON:API style · include/expand for related resources to avoid extra round trips · whitelist allowed fields and depth to protect the DB · trade-off vs GraphQL · watch cache keys, since different field sets mean different responses'),

  // ---- Node / Next.js server (8)
  q('How does the Node.js event loop differ from the browser event loop?', 'hard', ['Node / Next.js server', 'Must-have'],
    'both run one JS thread with a task queue and microtasks (promises) drained after each task · Node (libuv) has phases: timers, pending callbacks, poll (I/O), check (setImmediate), close callbacks · process.nextTick runs before promise microtasks · the browser interleaves rendering (rAF, paint) between tasks, Node has no rendering · CPU-heavy work blocks every request in Node, so use worker_threads or a queue'),
  q('Explain Node streams and backpressure. When would you stream a response?', 'hard', ['Node / Next.js server'],
    'Readable, Writable, Transform, Duplex · backpressure: write() returns false when the buffer passes highWaterMark, wait for drain · pipeline() wires streams and propagates errors and cleanup · stream large files, CSV exports and LLM tokens instead of buffering everything in memory · Web Streams (ReadableStream) in Next route handlers'),
  q('Next.js route handlers vs server actions — when do you use each?', 'medium', ['Node / Next.js server', 'Must-have'],
    'server actions: mutations from your own React UI, form progressive enhancement, typed calls, revalidatePath/revalidateTag after writes · they are still public POST endpoints, so authenticate and validate inside every action · route handlers: a real HTTP API for webhooks, third-party or mobile clients, GET with caching, streaming, custom headers · actions run sequentially and are not meant for data fetching'),
  q('What is Next.js middleware good for, and what should you not do in it?', 'medium', ['Node / Next.js server'],
    'runs before routing on every matched request · good for auth redirects, rewrites, A/B buckets, geo and locale, headers · keep it fast: no heavy DB queries, limited APIs, use matcher config to skip static assets · it is not the only security layer, verify auth again in the data layer and server actions'),
  q('Edge runtime vs Node runtime — trade-offs?', 'medium', ['Node / Next.js server'],
    'edge: low latency close to users, fast cold starts, Web APIs only, no native Node modules, limited CPU time and bundle size · node: full Node APIs, DB drivers and TCP connections, longer execution · edge is near the user but often far from the database, so DB-heavy routes can be slower · choose per route'),
  q('How do you handle long-running work (emails, PDF generation, AI jobs) from a web request?', 'hard', ['Node / Next.js server', 'Must-have'],
    'never block the request: enqueue a job and return 202 with a job id · a queue plus workers (BullMQ/Redis, SQS, Inngest, QStash) with retries, backoff and a dead-letter queue · idempotent jobs · progress through polling or SSE · serverless timeouts mean the work must run outside the request · track status in the DB'),
  q('How do you shut down a Node server gracefully?', 'medium', ['Node / Next.js server'],
    'handle SIGTERM (orchestrators send it before SIGKILL) · stop accepting new connections (server.close), fail the readiness probe first so the load balancer drains · let in-flight requests finish with a timeout · close DB pools, queues and flush logs · then exit · in-flight jobs must be resumable or idempotent'),
  q('What is structured logging and what would you log in an API?', 'easy', ['Node / Next.js server'],
    'JSON logs (pino) with level, timestamp, message and fields, not string concatenation · a request id / trace id propagated through calls and returned to the client · log method, route, status, latency, user id (not PII) · redact tokens, passwords and PII · correlate with traces (OpenTelemetry) and send to a central store'),

  // ---- Auth & security (7)
  q('Sessions vs JWT for a web app — which do you pick and why?', 'hard', ['Auth & security', 'Must-have'],
    'server sessions: opaque id in an HttpOnly cookie, state in the DB or Redis, instant revocation · JWT: stateless and signed, good across services, but cannot be revoked before expiry without a denylist and is often too large · for a browser app prefer an HttpOnly, Secure, SameSite cookie, never localStorage (XSS can read it) · short-lived access token + refresh token if you use JWTs · validate signature, exp, aud and iss'),
  q('How does refresh token rotation work?', 'hard', ['Auth & security'],
    'short-lived access token (minutes) + long-lived refresh token · every refresh returns a new refresh token and invalidates the old one · reuse of an old refresh token means theft, so revoke the whole token family · store refresh tokens in HttpOnly cookies, hashed server-side · handle concurrent refreshes in the client (a single in-flight refresh promise)'),
  q('Explain OAuth 2.0 Authorization Code with PKCE for a single-page app.', 'hard', ['Auth & security', 'Must-have'],
    'SPAs cannot keep a client secret, so PKCE replaces it: random code_verifier, SHA-256 code_challenge sent on the authorize request · redirect back with a code, exchange code + verifier for tokens · the state parameter prevents CSRF on the callback · the implicit flow is deprecated · better still, a BFF does the exchange server-side and gives the browser an HttpOnly session cookie'),
  q('How do you protect a cookie-authenticated app against CSRF?', 'medium', ['Auth & security'],
    'CSRF works because the browser attaches cookies to cross-site requests · SameSite=Lax/Strict cookies block most of it · anti-CSRF tokens (synchronizer or double-submit) for state-changing requests · check the Origin/Referer header · never change state on GET · JSON APIs with custom headers are safer but not a full defense on their own'),
  q('How do you implement role-based access control across the API and the UI?', 'medium', ['Auth & security'],
    'enforce on the server for every request and every server action, the UI only hides things · roles map to permissions and code checks permissions, not role names · resource-level checks (does this user own this record) or Postgres RLS · send the permission set to the client to hide buttons and routes · audit log for admin actions · test the denied paths'),
  q('How do you call an LLM API from a frontend without exposing the API key?', 'medium', ['Auth & security', 'AI backend'],
    'never ship the key to the browser · route through a BFF/API route that holds the key in a server env var · authenticate the user and rate limit per user · validate and cap input size and output tokens · stream the response through · log usage and cost per user · restrict models and tools server-side'),
  q('How would you implement rate limiting for an API?', 'medium', ['Auth & security'],
    'algorithms: fixed window, sliding window, token bucket (allows bursts) · key by user id, API key or IP · shared store (Redis, Upstash) so it works across instances · return 429 with Retry-After and RateLimit headers · different limits per route (login and expensive AI calls are stricter) · clients back off exponentially with jitter'),

  // ---- Data (8)
  q('Design the database schema for a kanban board or a small CRM.', 'hard', ['Data', 'Must-have'],
    'tables: users, workspaces/orgs, memberships with roles, boards, columns, cards (or contacts, deals, activities), comments · foreign keys and indexes on them · card ordering with a float or fractional index (lexorank) so a move does not renumber everything · created_at/updated_at, soft delete where needed · multi-tenancy through workspace_id on every row (RLS) · activity/audit table'),
  q('How do database indexes work, and when do they hurt?', 'medium', ['Data', 'Must-have'],
    'B-tree indexes turn full scans into lookups for equality, range and ORDER BY · composite index column order matters (leftmost prefix) · covering indexes avoid table lookups · they slow down writes and use storage, so unused or duplicate indexes cost · low-selectivity columns rarely help · check with EXPLAIN ANALYZE'),
  q('What is the N+1 query problem and how do you fix it?', 'medium', ['Data', 'Must-have'],
    'one query for a list plus one query per item, e.g. posts then each author · fix with a JOIN, an IN (...) batch, or ORM eager loading (include/select_related) · in GraphQL use DataLoader to batch per request · spot it in query logs or APM traces · also happens on the frontend as waterfall fetches'),
  q('Explain transactions and isolation levels at a practical level.', 'hard', ['Data'],
    'ACID: a transaction is all or nothing · isolation levels: read committed (Postgres default), repeatable read, serializable · anomalies: dirty read, non-repeatable read, phantom, lost update · fix lost updates with SELECT ... FOR UPDATE, optimistic locking on a version column, or atomic UPDATE ... SET x = x + 1 · keep transactions short and never hold one across a network call'),
  q('SQL vs NoSQL — how do you choose for a new product?', 'medium', ['Data'],
    'relational (Postgres) by default: joins, constraints, transactions, flexible queries, and JSONB covers semi-structured data · document stores fit access patterns known up front, flexible schemas and very high write scale · key-value (Redis) for cache and sessions · choose by access patterns, consistency needs and team skills, not hype · many products are Postgres plus Redis'),
  q('How do you run a database migration with zero downtime?', 'hard', ['Data'],
    'expand and contract: add the new column (nullable or with a default), deploy code that writes both, backfill in batches, switch reads, then drop the old column in a later deploy · never rename or drop in the same deploy as the code change · build indexes concurrently · avoid long table locks · migrations must be backward compatible with the running version'),
  q('What are your options for full-text search in an app?', 'medium', ['Data'],
    'Postgres full-text search (tsvector, GIN index, ranking) is enough for many apps · trigram (pg_trgm) for fuzzy and typo-tolerant matching · a dedicated engine (Elasticsearch, Meilisearch, Typesense, Algolia) for facets, typo tolerance and scale, at the cost of syncing data · semantic search with embeddings (pgvector) or hybrid ranking · debounce and cancel requests on the client'),
  q('Soft delete vs hard delete — trade-offs?', 'easy', ['Data'],
    'soft delete (deleted_at) allows undo, audit and restores, but every query must filter it (views or RLS) and unique constraints need partial indexes · hard delete is simpler and helps GDPR erasure · consider an archive table or event log · cascade behavior and orphaned rows · data retention policy'),

  // ---- Caching & performance (6)
  q('Walk through HTTP caching end to end for a web app.', 'hard', ['Caching & performance', 'Must-have'],
    'Cache-Control: max-age, s-maxage for CDNs, private vs public, no-store, immutable for hashed assets · validation with ETag/If-None-Match and Last-Modified returns 304 · stale-while-revalidate and stale-if-error · Vary for content negotiation · hashed static assets cached forever, HTML short or revalidated · never publicly cache personalized responses'),
  q('CDN cache vs application cache vs Redis — what goes where?', 'medium', ['Caching & performance'],
    'CDN: static assets and public, cacheable HTML/API responses at the edge · in-process memory cache: fastest but per instance and lost on deploy · Redis: shared across instances for sessions, rate limits, computed results and hot keys · choose by who shares the data and how fresh it must be · plan invalidation for each layer'),
  q('How would you invalidate the cache for a social feed?', 'hard', ['Caching & performance'],
    'cache invalidation is the hard part: TTLs plus event-driven invalidation on writes · key design (per user, per page or cursor) · fan-out on write (precomputed feeds) vs fan-out on read · versioned keys instead of deletes · tolerate eventual consistency for the feed but read-your-own-writes for the author · avoid a thundering herd (request coalescing, jittered TTLs)'),
  q('Explain stale-while-revalidate on the server and on the client.', 'medium', ['Caching & performance'],
    'serve the cached (possibly stale) value immediately and refresh it in the background · HTTP: Cache-Control stale-while-revalidate=N at the CDN · client: SWR and TanStack Query return cached data, refetch on mount, focus or interval, and dedupe requests · trade freshness for speed · show a subtle refreshing state, not a spinner'),
  q('What are the caching layers in the Next.js App Router?', 'hard', ['Caching & performance'],
    'request memoization (the same fetch deduped within one render) · Data Cache (fetch results across requests, revalidate by time or tag) · Full Route Cache (static HTML and RSC payload at build time or ISR) · client Router Cache · invalidate with revalidatePath and revalidateTag, opt out with no-store or dynamic APIs (cookies, headers) · in Next 15, fetch and GET route handlers are no longer cached by default'),
  q('How do you measure and improve p95 latency of an API?', 'medium', ['Caching & performance'],
    'p95 = 95% of requests are faster than this, averages hide the tail · measure with APM or tracing histograms per route (OpenTelemetry) · find the slow spans: DB queries (EXPLAIN, missing indexes, N+1), external calls, cold starts · fixes: indexes, caching, batching, parallel calls, timeouts, moving work to queues · set an SLO and alert on it'),

  // ---- AI backend (8)
  q('How do you stream LLM tokens to the browser — SSE or WebSocket?', 'hard', ['AI backend', 'Must-have'],
    'SSE: one-way server-to-client over plain HTTP, simple, auto-reconnect, works through proxies, fits token streaming · WebSocket: bidirectional, for real-time collaboration or voice, more infrastructure · server reads the provider stream and forwards chunks (ReadableStream or text/event-stream) · client appends tokens, handles abort (AbortController) and errors mid-stream · disable proxy buffering and keep chunks small'),
  q('How do you make LLM calls reliable: retries, timeouts and fallbacks?', 'medium', ['AI backend'],
    'timeouts on every call, streaming with a first-token timeout · retry 429 and 5xx with exponential backoff and jitter, never retry non-idempotent tool side effects blindly · fallback to another model or provider when the primary fails · circuit breaker · validate structured output (JSON schema) and retry on parse failure · show a graceful degraded state in the UI'),
  q('How do you log prompts and responses safely when they may contain PII?', 'medium', ['AI backend'],
    'log metadata by default (model, tokens, latency, cost, user id, request id) · redact or hash PII before storing prompts (emails, phones, names) · retention limits and access control on logs · opt-out and data-processing agreements with providers · keep logs for debugging and evals, sample if volume is high'),
  q('Walk through a basic RAG pipeline end to end.', 'hard', ['AI backend', 'Must-have'],
    'ingest: load docs, split into chunks (size and overlap), embed, store vectors with metadata · query: embed the question, retrieve top-k (optionally hybrid with keyword search and a reranker), build a prompt with the retrieved context and citations · generate the answer, grounded, saying it does not know when context is missing · evaluate retrieval and answer quality · re-index on document changes'),
  q('pgvector vs a dedicated vector database — how do you choose?', 'medium', ['AI backend'],
    'pgvector: vectors live next to relational data, joins and filters, transactions, RLS, one system to run · HNSW or IVFFlat indexes · dedicated DBs (Pinecone, Weaviate, Qdrant) for very large scale, managed sharding and advanced filtering · start with pgvector unless the scale demands otherwise · metadata filtering and hybrid search matter more than raw speed'),
  q('How do you control the cost of LLM features in production?', 'medium', ['AI backend'],
    'route cheap models for simple or structured tasks and big models only where needed · cache responses for identical prompts and use provider prompt caching · cap input and output tokens, trim context, summarize history · per-user budgets and rate limits · track cost per feature and per user · rules before AI: do not call an LLM for deterministic work'),
  q('How would you build a tool-calling (function-calling) backend for an AI assistant?', 'hard', ['AI backend'],
    'define tools with JSON schemas, the model returns tool calls, the server validates arguments and executes, results go back to the model in a loop until a final answer · allowlist tools per user and authorize every call server-side · require human approval for destructive actions · step limits and timeouts · log every call · stream intermediate steps to the UI'),
  q('How do you run evals for an LLM feature in CI?', 'hard', ['AI backend'],
    'a golden dataset of inputs with expected outputs or rubrics · deterministic checks (schema validity, required facts, banned content) plus LLM-as-judge with a fixed rubric · track scores over time and block merges on regressions · pin model versions and temperature · sample production traffic into the dataset · measure cost and latency too'),
  // ---- Row Level Security (8)
  q('What is Row Level Security in Postgres, and why use it instead of filtering in the API?', 'medium', ['Row Level Security', 'Must-have'],
    'RLS = policies on a table that Postgres adds to every query as an extra WHERE (USING) or check on written rows (WITH CHECK) · enable it per table; with RLS on and no policy, nothing is visible · defence in depth: a forgotten filter in one API route cannot leak other users\' rows · fits Supabase, where the browser talks to the database through PostgREST with the user\'s JWT · the API still validates input and business rules; RLS is about who can see and change which rows'),
  q('USING vs WITH CHECK in an RLS policy — what does each do, and what goes wrong if you only write one?', 'hard', ['Row Level Security', 'Must-have'],
    'USING filters which existing rows a SELECT, UPDATE or DELETE can see or touch · WITH CHECK validates the new row on INSERT and UPDATE · an UPDATE policy with only USING lets a user change user_id to someone else\'s (moving the row out of their own scope) · separate policies per command (select, insert, update, delete) are clearer than one FOR ALL · test each command as two different users'),
  q('How does Supabase know who the user is inside an RLS policy, and what does the service-role key change?', 'hard', ['Row Level Security', 'Must-have'],
    'the client sends the user\'s JWT; PostgREST sets the role (anon or authenticated) and the JWT claims for the request · auth.uid() reads the sub claim, so policies compare it to user_id · the anon key is public and safe only because RLS is on · the service-role key bypasses RLS: server-only (cron, webhooks, admin jobs), never in the browser or a NEXT_PUBLIC_ variable · with the service role, every query must filter by user itself'),
  q('How would you write RLS for a multi-tenant app where users belong to organizations with roles?', 'hard', ['Row Level Security'],
    'a memberships table (user_id, org_id, role) and org_id on every tenant table · policies check EXISTS a membership for auth.uid() and the row\'s org_id, with role checks for writes · wrap the lookup in a SECURITY DEFINER function or use JWT custom claims to avoid recursive policies and repeated joins · index memberships(user_id, org_id) · how you stop a user inserting a row into an org they are not in (WITH CHECK)'),
  q('RLS made a query slow — how do you find and fix it?', 'hard', ['Row Level Security'],
    'the policy runs per row, so a function call or subquery in it can run thousands of times · EXPLAIN ANALYZE as the real role (set role authenticated plus the JWT claims) to see the plan with policies applied · index the columns the policy filters on (user_id, org_id) · wrap auth.uid() in (select auth.uid()) so Postgres evaluates it once, not per row · also add the same filter in the query so the planner can use the index'),
  q('What are the common RLS mistakes that leak data?', 'medium', ['Row Level Security'],
    'forgetting to enable RLS on a new table (it is off by default) · a policy of USING (true) left from testing · views that run as their owner and bypass RLS (use security_invoker) · SECURITY DEFINER functions that return rows without checking the caller · storage buckets and realtime channels needing their own policies · trusting a user-editable column (like a role in user metadata) inside a policy'),
  q('How do you test RLS policies?', 'medium', ['Row Level Security'],
    'test as real roles, not as the table owner or service role · two users: A must not read, update or delete B\'s rows, and cannot insert a row with B\'s user_id · anon must see nothing private · run the tests in CI against a local database (pgTAP, or a script with two signed-in clients) · re-run them in every migration that adds a table'),
  q('RLS vs authorization in your application code — where does each check belong?', 'medium', ['Row Level Security'],
    'RLS: row ownership and tenant isolation, enforced however the data is reached · app code: business rules (plan limits, state transitions, approval flows), input validation, rate limits · server actions and route handlers still authenticate the user · keep the rules in one place per concern so they do not drift · when you would skip RLS (a single backend owns all DB access with its own service account)'),

  // ---- FastAPI (8)
  q('Why FastAPI? How does it compare to Express or Next.js route handlers for an AI backend?', 'medium', ['FastAPI', 'Must-have'],
    'Python, so the AI and data libraries (LangChain, transformers, NumPy, Pydantic) are native · type hints drive validation, serialization and OpenAPI docs automatically · async support on ASGI (Uvicorn) · Express or Next.js handlers keep one language with the frontend and share types · a common split: Next.js for the UI and BFF, FastAPI for model, RAG and data services'),
  q('How does FastAPI use Pydantic for request and response validation?', 'medium', ['FastAPI', 'Must-have'],
    'request bodies as Pydantic models: invalid input returns a 422 with the field errors, before your code runs · response_model filters and validates the output (so internal fields like password hashes never leak) · path and query params typed in the function signature · Pydantic v2 is fast (Rust core) and supports validators and computed fields · the OpenAPI schema is generated from the same models, so TypeScript clients can be generated from it'),
  q('async def vs def in FastAPI — what actually happens, and how can you block the event loop?', 'hard', ['FastAPI', 'Must-have'],
    'async def endpoints run on the event loop; plain def endpoints run in a thread pool · calling a blocking library (requests, a sync DB driver, time.sleep, heavy CPU work) inside async def freezes every request on that worker · use async clients (httpx, asyncpg, the async OpenAI SDK) or move sync work to def or run_in_threadpool · CPU-heavy work (embeddings, parsing) to a worker process or queue · how you would spot it (latency for all requests rising together)'),
  q('What is dependency injection in FastAPI (Depends), and what do you use it for?', 'medium', ['FastAPI'],
    'Depends declares what an endpoint needs; FastAPI resolves and caches it per request · typical uses: the current user from a bearer token, a DB session with cleanup (yield dependencies), settings, pagination params · dependencies compose (get_user depends on get_token) · easy to override in tests (app.dependency_overrides) · router-level dependencies to protect a group of routes'),
  q('How do you add authentication to a FastAPI service that sits behind a Next.js app?', 'hard', ['FastAPI'],
    'pick who the client is: the browser directly (verify the same JWT, e.g. a Supabase or Keycloak token, against the JWKS) or only the Next.js server (a service token or mTLS, never exposed to the browser) · a Depends that verifies signature, expiry, audience and issuer, then returns the user · pass the user id through to queries or RLS · CORS only for the origins that should call it · rate limit per user'),
  q('How do you stream an LLM response from FastAPI to a React client?', 'hard', ['FastAPI'],
    'StreamingResponse with an async generator yielding tokens, or Server-Sent Events (text/event-stream, sse-starlette) · disable proxy buffering (X-Accel-Buffering: no) and keep the connection alive · detect client disconnect (request.is_disconnected) and cancel the model call to save tokens · on the client: fetch with a ReadableStream reader or EventSource, append tokens to state, an abort controller for Stop · send an error event instead of cutting the stream silently'),
  q('Background tasks in FastAPI vs a real job queue — when is each enough?', 'medium', ['FastAPI'],
    'BackgroundTasks run after the response in the same process: fine for small fire-and-forget work (send an email, write a log) · lost if the process restarts, no retries, no visibility · long or important work (document ingestion, embeddings, reports) goes to a queue with workers (Celery, RQ, Arq, Dramatiq) · return 202 with a job id and let the UI poll or subscribe for progress'),
  q('How do you structure, test and deploy a FastAPI project?', 'medium', ['FastAPI'],
    'APIRouter per feature, schemas (Pydantic) separate from DB models, services for business logic, settings with pydantic-settings from env vars · lifespan events to open and close DB pools and model clients · tests with TestClient or httpx.AsyncClient and dependency overrides · run with Uvicorn (or Gunicorn with Uvicorn workers) in a slim Docker image with a health check · migrations with Alembic'),

  // ---- Next.js rendering (10)
  q('Where should the \'use client\' boundary go, and what can and cannot cross it?', 'hard', ['Next.js rendering', 'Must-have'],
    '\'use client\' marks an entry point: that file and everything it imports become client code · push it down to the leaves (a button, a form), not the page or layout · props from server to client must be serializable (no functions except Server Actions, no class instances, Dates become strings in some cases) · a client component can render server components passed as children or props · importing a server-only module in a client file breaks the build, which is what you want'),
  q('How does Next.js decide whether a route is static or dynamic, and how do you control it?', 'hard', ['Next.js rendering', 'Must-have'],
    'static by default: rendered at build time and cached · reading cookies(), headers(), searchParams, or an uncached fetch makes it dynamic (rendered per request) · control: export const dynamic, revalidate = N (ISR), fetch cache and next.revalidate options, generateStaticParams for dynamic segments · check the build output (○ static, ƒ dynamic) · one accidental cookies() in a layout makes every page under it dynamic'),
  q('SSR, SSG, ISR and Partial Prerendering in the App Router — how do you pick for a page?', 'hard', ['Next.js rendering', 'Must-have'],
    'SSG: same for everyone and changes rarely (marketing, docs) · ISR: mostly static but must update (product pages, revalidate by time or tag) · SSR: per-user or per-request data (dashboards, search results) · PPR: a static shell sent instantly with dynamic holes streamed in through Suspense · decide per route by freshness, personalization and SEO, and measure TTFB and LCP'),
  q('What causes a hydration mismatch, and how do you fix one?', 'medium', ['Next.js rendering', 'Must-have'],
    'the server HTML and the first client render differ · common causes: Date.now() or Math.random() in render, locale and timezone formatting, reading window or localStorage during render, invalid HTML nesting (a div inside a p), browser extensions changing the DOM · fixes: move client-only values into useEffect, render them only after mount, pass the value from the server, or suppressHydrationWarning for a single known case like a timestamp · read the diff React prints'),
  q('How do you keep secrets and server-only code out of the client bundle in Next.js?', 'medium', ['Next.js rendering'],
    'only NEXT_PUBLIC_ variables are inlined into the browser bundle; everything else stays on the server · import \'server-only\' in modules with secrets or DB access so a client import fails the build · do not pass secrets or whole DB rows as props to client components; pass only the fields the UI needs · the React taint APIs as an extra guard · check the built client chunks when unsure'),
  q('Server Actions are public endpoints — how do you secure them?', 'hard', ['Next.js rendering'],
    'every exported action in a \'use server\' file can be called with any arguments by anyone who finds its id · authenticate inside the action, every time; do not rely on the page having checked · validate arguments (zod) and authorize the specific resource (does this user own this row) · rate limit expensive ones · Next.js checks the Origin header against CSRF, but that is not authorization · return safe error messages, not stack traces'),
  q('Fetching data in a Server Component vs on the client with TanStack Query — when do you use each?', 'medium', ['Next.js rendering'],
    'Server Components: initial data close to the database, no client JS, no loading spinner on first paint, secrets stay on the server · client fetching: data that changes after load (polling, infinite scroll, filters typed by the user), optimistic updates, offline · a common mix: fetch on the server, pass as initial data, let the client cache take over · avoid fetching the same data in both places with different cache rules'),
  q('How do loading.tsx, error.tsx and Suspense boundaries shape what the user sees?', 'medium', ['Next.js rendering'],
    'loading.tsx wraps the page in a Suspense boundary so navigation shows a skeleton at once · error.tsx is a client error boundary for its segment, with reset() to retry; global-error.tsx for the root layout · nested Suspense boundaries let fast parts show while slow parts stream in · place boundaries around slow, independent data, not around everything · not-found.tsx with notFound() for missing resources'),
  q('How do you share state like a theme or the current user across a Next.js App Router app?', 'medium', ['Next.js rendering'],
    'Context only works in client components, so wrap providers in one small \'use client\' Providers component inside the root layout · server components can still render inside it as children · read per-request data (the user) on the server and pass it to the provider as an initial value · avoid a global store for server data; use the server or a query cache · theme without a flash: a cookie read on the server or an inline script before paint'),
  q('After a mutation, how do you make the UI show fresh data in the App Router?', 'medium', ['Next.js rendering'],
    'revalidatePath or revalidateTag inside the Server Action or route handler so the cached data and route are refreshed · router.refresh() on the client re-renders server components without losing client state · useOptimistic to show the change before the server confirms, and roll back on error · tag fetches by resource so one write invalidates exactly the right data · the trade-off of revalidating whole paths on every small write (slower responses)'),
  // ---- Python asyncio (9)
  q('asyncio.gather vs asyncio.wait — what is the difference, and when do you use each?', 'medium', ['Python asyncio', 'Must-have'],
    'gather(*aws) runs awaitables concurrently and returns their results in the same order as passed; it takes coroutines and wraps them in tasks · wait(tasks, return_when=...) takes tasks and returns two sets (done, pending), with FIRST_COMPLETED, FIRST_EXCEPTION or ALL_COMPLETED, plus a timeout · gather is for "run all, give me all results"; wait is for control: react to the first one done, time out and cancel the rest · wait does not raise or cancel for you — you read results from done tasks and cancel pending ones yourself · TaskGroup (3.11+) is the modern default for "run all" with safe cancellation'),
  q('With asyncio.gather, what happens to the other tasks when one raises — and what does return_exceptions=True change?', 'hard', ['Python asyncio', 'Must-have'],
    'by default the first exception propagates to the caller of gather, but the other tasks are NOT cancelled — they keep running in the background · return_exceptions=True returns exceptions as values in the result list, so you check each one · cancelling the gather cancels all its children · TaskGroup cancels the siblings when one fails and raises an ExceptionGroup (handled with except*) · always decide: fail fast and cancel, or collect partial results'),
  q('asyncio.TaskGroup vs gather — what is structured concurrency, and why prefer it?', 'medium', ['Python asyncio'],
    'async with asyncio.TaskGroup() as tg: tg.create_task(...) — every task finishes (or is cancelled) before the block exits · if one task fails, the rest are cancelled and the errors raised together as an ExceptionGroup · no orphan tasks still running after an error · clearer lifetimes, like try/finally for tasks · gather is still fine for a quick "all results in order" when failures are handled'),
  q('How do timeouts and cancellation work in asyncio?', 'hard', ['Python asyncio'],
    'asyncio.timeout(seconds) (3.11+) or wait_for(aw, timeout) cancel the awaited work and raise TimeoutError · cancellation is delivered as CancelledError at the next await point · catch it only to clean up (close connections, release locks) and re-raise; swallowing it breaks cancellation · put a timeout on every network call · shield() protects work that must finish, used rarely'),
  q('You need to call an API 1,000 times concurrently without getting rate-limited. How do you do it with asyncio?', 'medium', ['Python asyncio'],
    'an asyncio.Semaphore(n) around each call limits how many run at once · or a fixed pool of worker tasks reading from an asyncio.Queue · one shared httpx.AsyncClient for connection reuse · retry 429 / 5xx with backoff and jitter · as_completed or a TaskGroup to collect results, with per-item error handling so one failure does not lose the batch'),
  q('What does asyncio.as_completed do, and when is it better than gather?', 'easy', ['Python asyncio'],
    'it yields awaitables in the order they finish, not the order you started them · lets you process or stream each result as soon as it is ready (show progress, write to the DB) · gather waits for all and returns them in input order · combine with a timeout to stop waiting on stragglers'),
  q('asyncio vs threads vs processes in Python — how do you choose, and where does the GIL matter?', 'hard', ['Python asyncio', 'Must-have'],
    'asyncio: one thread, many I/O-bound tasks (HTTP calls, DB queries), cheap concurrency but nothing may block · threads: I/O-bound work with blocking libraries; the GIL lets only one thread run Python bytecode at a time · processes (multiprocessing, ProcessPoolExecutor): CPU-bound work in parallel across cores · bridge sync code into asyncio with asyncio.to_thread or run_in_executor · free-threaded Python (3.13+, no GIL) is experimental'),
  q('Coroutine vs Task vs Future — and what bugs come from a missing await or a fire-and-forget task?', 'medium', ['Python asyncio'],
    'a coroutine is a paused function that does nothing until awaited or scheduled · a Task schedules a coroutine on the event loop; a Future is the low-level result placeholder · a missing await means the work never runs ("coroutine was never awaited" warning) · create_task without keeping a reference can be garbage-collected mid-run, and its exceptions are lost · keep references (a set, or a TaskGroup) and log task exceptions'),
  q('Map asyncio to JavaScript: what are the equivalents of Promise.all, allSettled, race and any?', 'easy', ['Python asyncio', 'Must-have'],
    'Promise.all ≈ gather (or TaskGroup): all results, fails on the first error · allSettled ≈ gather(return_exceptions=True) · race ≈ wait(return_when=FIRST_COMPLETED), then cancel the pending ones · any ≈ as_completed, taking the first success · key difference: JS promises start running immediately; Python coroutines only run once awaited or wrapped in a task, and asyncio tasks can be cancelled'),

  // ---- Concurrency & deadlocks (8)
  q('What is a deadlock, what conditions cause it, and how do you prevent and handle one?', 'hard', ['Concurrency & deadlocks', 'Must-have'],
    'two or more workers each hold a resource and wait for one the other holds, so nobody progresses · the four conditions: mutual exclusion, hold and wait, no preemption, circular wait — break any one · prevention: acquire locks in one global order, hold them briefly, take all you need at once · handling: lock timeouts (acquire(timeout=...)), detect and retry (Postgres aborts one side), alert on long waits · a concrete example you have seen or would test'),
  q('Two transactions deadlock in Postgres. Why does it happen, and how do you fix it?', 'hard', ['Concurrency & deadlocks', 'Must-have'],
    'transaction A locks row 1 then wants row 2 while B locks row 2 then wants row 1 · Postgres detects the cycle (deadlock_timeout) and aborts one with error 40P01 · fix: update rows in a consistent order (e.g. ORDER BY id), keep transactions short, no user or network waits inside a transaction · retry the aborted transaction with backoff · find it in the logs (log_lock_waits) and pg_locks'),
  q('How can you deadlock asyncio code even with a single thread?', 'hard', ['Concurrency & deadlocks'],
    'asyncio.Lock is not reentrant: a coroutine that awaits a function which takes the same lock waits on itself forever · two tasks awaiting each other\'s result (or events set by each other) · queue.join() with no consumer running, or a bounded queue whose producer waits while the consumer waits on the producer · calling a blocking sync call inside the loop that waits for work only the loop can do · fixes: timeouts, one lock order, restructuring to avoid nested locking'),
  q('Race condition vs deadlock vs livelock vs starvation — explain each with an example.', 'medium', ['Concurrency & deadlocks'],
    'race condition: the result depends on timing (two requests read balance 100, both write 90) · deadlock: workers wait on each other forever · livelock: workers keep reacting to each other and retrying without progress (two people stepping aside in a corridor) · starvation: one worker never gets the resource because others keep winning · fixes: atomic operations or locks, lock ordering, backoff with jitter, fair queues'),
  q('Optimistic vs pessimistic locking — how do they work, and when do you use each?', 'medium', ['Concurrency & deadlocks'],
    'pessimistic: lock the row first (SELECT ... FOR UPDATE), others wait — safe under heavy contention, risks waits and deadlocks · optimistic: read with a version column, UPDATE ... WHERE id = ? AND version = ?, retry if 0 rows changed — no locks held, best when conflicts are rare · atomic single statements (UPDATE balance = balance - 10) avoid both · SKIP LOCKED for job queues'),
  q('threading.Lock vs RLock in Python, and why should you use timeouts?', 'medium', ['Concurrency & deadlocks'],
    'Lock: one holder, and the same thread acquiring it twice deadlocks itself · RLock: the owning thread can re-acquire it (counts acquisitions), useful for recursive or nested calls · always use with-blocks so locks are released on exceptions · acquire(timeout=...) turns a silent hang into an error you can log and handle · prefer queues and immutable data to sharing state with locks'),
  q('How do distributed locks work (e.g. with Redis), and what can go wrong?', 'hard', ['Concurrency & deadlocks'],
    'SET key value NX PX ttl to take the lock, a unique value so only the owner releases it (Lua compare-and-delete) · the TTL frees the lock if the holder crashes — but a slow holder may still be working after it expires · fencing tokens (an increasing number checked by the resource) stop a stale holder from writing · Redlock is debated; for correctness prefer the database (advisory locks, unique constraints) · make the protected work idempotent'),
  q('A Python service hangs in production. How do you find out whether it is a deadlock?', 'hard', ['Concurrency & deadlocks'],
    'check whether CPU is idle (waiting) or busy (a loop) · dump thread and task stacks: py-spy dump, faulthandler, asyncio.all_tasks() with their stacks · in the database: pg_stat_activity (state, wait_event) and pg_locks to see who blocks whom · logs around lock acquisition with timings · add timeouts and a watchdog so the next one fails loudly instead of hanging'),

  // ---- Caching in deployment (8)
  q('How do you cache a web app\'s assets so users get fast loads but never stale code after a deploy?', 'medium', ['Caching in deployment', 'Must-have'],
    'content-hashed file names for JS/CSS/images (app.3f9a1.js) with Cache-Control: public, max-age=31536000, immutable · HTML (and the service worker) with no-cache or a short max-age so it always points at the new hashes · the CDN serves assets from the edge; a deploy uploads new hashed files instead of overwriting · keep old assets for a while so open tabs still work · API responses get their own, shorter rules'),
  q('After a deploy, users see "ChunkLoadError" or "Failed to fetch dynamically imported module". Why, and how do you fix it?', 'hard', ['Caching in deployment', 'Must-have'],
    'an open tab (or cached HTML) still references old chunk hashes that the new deploy deleted · fixes: keep previous deploys\' assets for days (immutable storage, skew protection on Vercel), never cache HTML long · catch the error in the router or an error boundary and reload once to pick up the new version · notify users a new version is available · test by deploying while a tab is open'),
  q('CDN cache invalidation on deploy — versioned URLs or purging? What are the trade-offs?', 'medium', ['Caching in deployment'],
    'versioned or hashed URLs never need a purge: new content gets a new URL, best for assets · purge (by path, tag or everything) is for content at stable URLs like HTML or images · purging everything causes a load spike on the origin and costs time to propagate · surrogate keys or cache tags purge exactly what changed · s-maxage plus stale-while-revalidate keeps it fast while refreshing'),
  q('How do you order a Dockerfile so builds are fast, and what is BuildKit cache mounting?', 'medium', ['Caching in deployment'],
    'each instruction is a layer, reused until something in it or above it changes · copy the lockfile and install dependencies before copying the source, so a code change does not reinstall everything · multi-stage builds: a heavy build stage, a slim runtime image · RUN --mount=type=cache keeps the npm / pip cache between builds · a .dockerignore so node_modules and .git do not bust the cache'),
  q('How do you cache in CI to speed up builds, and how can a cache cause wrong builds?', 'medium', ['Caching in deployment'],
    'cache dependencies keyed on the lockfile hash (actions/cache, setup-node cache) · cache build outputs: .next/cache, Turborepo or Nx remote cache keyed on inputs · risks: a key that misses an input (env vars, Node version) restores a stale or wrong artifact · poisoned caches from untrusted pull requests · always include the toolchain version in the key and be able to run with the cache off'),
  q('Right after a deploy the database gets hammered because the cache is cold. How do you prevent a cache stampede?', 'hard', ['Caching in deployment', 'Must-have'],
    'many requests miss the same key at once and all hit the database · request coalescing / single-flight: one request recomputes, the rest wait for it · a lock or "recompute early" (probabilistic early expiry) before the TTL ends · jitter on TTLs so keys do not expire together · warm the hottest keys during deploy, and roll out gradually so the cache fills before full traffic'),
  q('You changed the shape of an object you store in Redis. How do you deploy without breaking things?', 'medium', ['Caching in deployment'],
    'old cached values will be read by the new code (and new values by old code during a rolling deploy) · version the cache key (user:v2:123) so each version reads its own entries · or make readers tolerant: validate cached data and treat bad data as a miss · let old keys expire with their TTL instead of flushing everything at once · same rule as API changes: backward compatible first'),
  q('With blue-green or canary deploys, two versions run at once. What does that mean for caches and clients?', 'hard', ['Caching in deployment'],
    'old and new servers share the same CDN, Redis and database, so cached data and responses must work for both · version cache keys or keep formats compatible · pin a user to one version during the rollout (sticky routing, skew protection) to avoid mixing old HTML with new APIs · a service worker can keep serving the old app until it updates — handle the update prompt · rollback must also work with what the new version cached'),

  // ---- SOLID & design in Python (9)
  q('Explain the SOLID principles, with a short Python example for each.', 'medium', ['SOLID & design', 'Must-have'],
    'S — single responsibility: a class has one reason to change (split a ReportService that fetches, formats and emails) · O — open/closed: add behaviour by adding code, not editing it (a new PaymentMethod subclass or a registered strategy instead of another elif) · L — Liskov substitution: a subclass works anywhere its parent does (same inputs accepted, same kind of output, no surprise exceptions) · I — interface segregation: small Protocols instead of one fat base class · D — dependency inversion: depend on a Protocol and inject the implementation (pass a repository into the service) · keep it practical: in Python, functions and Protocols often replace class hierarchies'),
  q('What bugs do you get in Python code that breaks the SOLID principles?', 'hard', ['SOLID & design', 'Must-have'],
    'SRP broken: a god class where a change to email formatting breaks report generation, and tests need the whole world · OCP broken: long if/elif chains on a type string — a new case is forgotten in one of the copies and falls through silently · LSP broken: a subclass that raises NotImplementedError or returns None / a different type, so callers crash at run time (Python will not stop it at import) · ISP broken: classes forced to implement dummy methods that do nothing or raise, so a call "works" but does nothing · DIP broken: hard-coded clients and globals make code untestable, tests hit real services, and swapping the DB means editing business logic · one real example from your own code'),
  q('Explain Liskov substitution with an example where it breaks, and how type hints and tests help in Python.', 'hard', ['SOLID & design', 'Must-have'],
    'classic case: Square extends Rectangle, setting width also changes height, so code that sets width and height then checks the area breaks · Python example: a ReadOnlyRepo subclass whose save() raises, passed to code expecting a Repo · rules: accept at least what the parent accepts, return what it promises, raise no new kinds of errors, keep its invariants · mypy / pyright catch signature and return-type mismatches when you annotate · shared contract tests run against every implementation'),
  q('How do you apply dependency inversion in Python — ABCs, Protocols, or just passing functions?', 'medium', ['SOLID & design'],
    'high-level code (the service) depends on an abstraction, not a concrete client · typing.Protocol gives structural typing: anything with the right methods fits, no inheritance needed · abc.ABC when you want shared code or to enforce implementation at instantiation · inject through the constructor or a parameter; FastAPI Depends does it per request · in tests pass a fake; simple cases can just take a function'),
  q('How do you remove a long if/elif chain on types in Python (open/closed principle)?', 'medium', ['SOLID & design'],
    'polymorphism: each type implements its own method · a dict registry mapping a key to a handler function or class, plus a decorator to register new ones · functools.singledispatch to dispatch on argument type · match statements are fine for a closed set of cases, not an open one · a clear error for an unknown key instead of a silent default'),
  q('typing.Protocol vs abc.ABC — how do they support interface segregation?', 'medium', ['SOLID & design'],
    'ABC: nominal — classes must inherit and implement every abstract method, or instantiation fails · Protocol: structural — any object with the right methods matches, checked by the type checker (runtime_checkable for isinstance) · small, focused Protocols (Reader, Writer) instead of one big Storage interface · clients depend only on the methods they use · Protocols fit Python\'s duck typing and third-party classes you cannot change'),
  q('When is applying SOLID overkill in Python?', 'medium', ['SOLID & design'],
    'Python favours simple functions and modules; a class hierarchy for one implementation is premature · YAGNI: add the abstraction when the second implementation or a test needs it · too many tiny classes and indirections make code harder to follow and debug · composition over inheritance, and plain data classes for data · the goal is easy-to-change, testable code, not following a checklist'),
  q('Which design patterns do you actually use in a Python backend, and why?', 'medium', ['SOLID & design'],
    'strategy: swap algorithms (pricing rules, LLM providers) behind one interface · factory: build the right client from config · adapter: wrap a third-party SDK so the rest of the code does not depend on it · repository: hide database access behind methods, easy to fake in tests · dependency injection to wire it all · decorators for cross-cutting concerns (retries, timing, caching)'),
  q('Refactor this: one 200-line Python function fetches data, validates it, calculates totals, saves to the DB and sends an email. How do you split and test it?', 'hard', ['SOLID & design'],
    'separate pure logic (validate, calculate) from side effects (fetch, save, email) · pure functions get fast unit tests with plain inputs and outputs · side effects behind small injected interfaces (repository, mailer) so tests use fakes · a thin orchestrating function calls them in order · refactor in small steps behind existing tests (add characterization tests first) · errors handled at the boundary, and the email sent only after the save succeeds'),
]

// Must-haves first, otherwise the order above.
const must = r => r.topics.includes('Must-have') ? 0 : 1
export default [...ROWS].sort((a, b) => must(a) - must(b)).map((r, i) => ({ ...r, sort_order: i + 1 }))
